CREATE TABLE canonical_users (id UUID PRIMARY KEY, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE credential_links (id UUID PRIMARY KEY, canonical_user_id UUID NOT NULL REFERENCES canonical_users(id), provider TEXT NOT NULL, issuer TEXT NOT NULL, subject TEXT NOT NULL, standing TEXT NOT NULL, linked_at TIMESTAMPTZ NOT NULL, revoked_at TIMESTAMPTZ, UNIQUE(provider,issuer,subject));
CREATE TABLE credential_proofs (id UUID PRIMARY KEY, credential_link_id UUID REFERENCES credential_links(id), provider TEXT NOT NULL, issuer TEXT NOT NULL, subject TEXT NOT NULL, proof_type TEXT NOT NULL, proof_version TEXT NOT NULL, verified_at TIMESTAMPTZ NOT NULL, claims_json JSONB NOT NULL, source_reference TEXT);
CREATE TABLE link_intents (id UUID PRIMARY KEY, canonical_user_id UUID NOT NULL REFERENCES canonical_users(id), initiating_session_id TEXT NOT NULL, provider TEXT NOT NULL, issuer TEXT NOT NULL, toolkit_id TEXT NOT NULL, tenant_id TEXT NOT NULL, client_id TEXT NOT NULL, redirect_uri TEXT NOT NULL, state_hash TEXT NOT NULL UNIQUE, nonce_hash TEXT, pkce_challenge TEXT, status TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL, expires_at TIMESTAMPTZ NOT NULL, consumed_at TIMESTAMPTZ);
CREATE TABLE auth_intents (id UUID PRIMARY KEY, nonce_hash TEXT NOT NULL UNIQUE, domain TEXT NOT NULL, audience TEXT NOT NULL, requested_chains_json JSONB NOT NULL, issued_at TIMESTAMPTZ NOT NULL, expires_at TIMESTAMPTZ NOT NULL, consumed_at TIMESTAMPTZ);
CREATE TABLE identity_sessions (id UUID PRIMARY KEY, canonical_user_id UUID NOT NULL REFERENCES canonical_users(id), token_hash TEXT NOT NULL UNIQUE, created_at TIMESTAMPTZ NOT NULL, expires_at TIMESTAMPTZ NOT NULL, revoked_at TIMESTAMPTZ);
CREATE TABLE identity_audit_events (id UUID PRIMARY KEY, event_type TEXT NOT NULL, canonical_user_id UUID, credential_storage_key TEXT, occurred_at TIMESTAMPTZ NOT NULL, details_json JSONB NOT NULL);
